class Result(object):
    '''The result of a parse() or search() operation.

    The fixed positional values can be retrieved via indexing/slicing,
    as can the named values as a dict.
    '''
    def __init__(self, fixed, named, spans):
        self.fixed = fixed
        self.named = named
        self.spans = spans

    def __getitem__(self, item):
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]

    def __contains__(self, item):
        """Check if item is in fixed or named."""
        return item in self.fixed or item in self.named

    def __len__(self):
        return len(self.fixed)

    def __iter__(self):
        return iter(self.fixed)

    def __repr__(self):
        return '<%s %r %r>' % (self.__class__.__name__, self.fixed,
            self.named)

    def __getitem__(self, item):
        if isinstance(item, int):
            return self.fixed[item]
        elif isinstance(item, slice):
            # Slice access - return tuple for integer slices, Result for string slices
            if isinstance(item.start, int) or isinstance(item.stop, int) or isinstance(item.step, int):
                return self.fixed[item]
            return self.named[item]
        return self.named[item]

